// ==== Changes list hydration ====
// Populate #changes-list from site/log.json (newest first) so the Changes
// page is never empty. If log.json is missing, the static HTML is left intact.
function hydrateChangesList() {
  const list = document.getElementById('changes-list');
  if (!list) return;
  fetch('log.json')
    .then(r => r.json())
    .then(entries => {
      const sorted = Array.from(entries).sort((a, b) =>
        String(b.run_at || '').localeCompare(String(a.run_at || ''))
      );
      list.textContent = '';
      sorted.forEach(entry => {
        const li = document.createElement('li');
        const when = entry.run_at || entry.date || '';
        const what = entry.changed_paths || '';
        li.textContent = when + ' — ' + (entry.state || '') + (what ? ' — ' + what : '');
        list.appendChild(li);
      });
    })
    .catch(() => {
      // log.json unavailable; leave the list empty
    });
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', hydrateChangesList);
} else {
  hydrateChangesList();
}
```

