// ==== Changes list hydration ====
// Populate #changes-list (changes.html) from site/log.json, newest first, so
// the page is never empty and the export buttons above have rows to read.
// If log.json is missing, the list is left as-is.
function hydrateChangesList() {
  const list = document.getElementById('changes-list');
  if (!list) return;
  fetch('log.json')
    .then(r => r.json())
    .then(entries => {
      const rows = Array.from(entries || []).sort((a, b) =>
        String(b.run_at || '').localeCompare(String(a.run_at || ''))
      );
      list.textContent = '';
      rows.forEach(entry => {
        const li = document.createElement('li');
        const when = entry.run_at || entry.date || '';
        const what = entry.changed_paths || '';
        li.textContent = when + ' — ' + (entry.state || '') + (what ? ' — ' + what : '');
        list.appendChild(li);
      });
    })
    .catch(() => {
      // log.json unavailable; leave the list empty
    });
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', hydrateChangesList);
} else {
  hydrateChangesList();
}
